+package test.com.sun.javafx.pgstub;
+
+import com.sun.javafx.font.Glyph;
+
+import org.junit.jupiter.api.Test;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+public class StubGlyphTest {
+
+    @Test
+    public void regularGlyphShouldMatchTheAdvance() {
+        Glyph glyph = new StubGlyph('M', 20);
+
+        assertEquals(20, glyph.getWidth());
+        assertEquals(20, glyph.getBBox().getMaxX());
+    }
+
+    @Test
+    public void italicGlyphShouldOverhangTheAdvance() {
+        Glyph regular = new StubGlyph('M', 20, false);
+        Glyph italic = new StubGlyph('M', 20, true);
+
+        assertTrue(italic.getWidth() > 20);  // must be wider than advance to be italic
+        assertTrue(italic.getWidth() > regular.getWidth());  // must be wider than a regular glyph
+        assertEquals(20, regular.getWidth());
+    }
+}

